using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
namespace Underwater.Editor {
// Deterministic geometry generators. All meshes are written as editable Unity assets.
public class ReefGeometry {
 readonly List<Vector3> v=new();readonly List<Vector2> uv=new();readonly List<Color> colors=new();readonly List<int> tris=new();
 public int Vertex(Vector3 p,Vector2 t,Color c){int i=v.Count;v.Add(p);uv.Add(t);colors.Add(c);return i;}
 public void Tri(int a,int b,int c){tris.Add(a);tris.Add(b);tris.Add(c);}
 public void Quad(int a,int b,int c,int d){Tri(a,b,c);Tri(a,c,d);}
 public Mesh Mesh(string name){var m=new Mesh{name=name,indexFormat=v.Count>65000?IndexFormat.UInt32:IndexFormat.UInt16};m.SetVertices(v);m.SetUVs(0,uv);m.SetColors(colors);m.SetTriangles(tris,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return m;}
 public void Tube(Vector3[] p,float[] radii,int sides,Color c){int start=v.Count;
  for(int i=0;i<p.Length;i++){Vector3 tangent=(p[Mathf.Min(i+1,p.Length-1)]-p[Mathf.Max(0,i-1)]).normalized;Vector3 u=Vector3.Cross(tangent,Mathf.Abs(tangent.y)>.9f?Vector3.right:Vector3.up).normalized;Vector3 w=Vector3.Cross(tangent,u);
   for(int j=0;j<=sides;j++){float a=j*Mathf.PI*2/sides;Color tint=c*Mathf.Lerp(.65f,1,(float)i/(p.Length-1));tint.a=1;Vertex(p[i]+(u*Mathf.Cos(a)+w*Mathf.Sin(a))*radii[i],new Vector2((float)j/sides,(float)i/(p.Length-1)),tint);}}
  for(int i=0;i<p.Length-1;i++)for(int j=0;j<sides;j++){int a=start+i*(sides+1)+j;Quad(a,a+1,a+sides+2,a+sides+1);}
 }
 public void Ellipsoid(Vector3 center,Vector3 scale,int lat=16,int lon=24,float noise=0,int seed=0){int start=v.Count;
  for(int i=0;i<=lat;i++){float theta=(float)i/lat*Mathf.PI;for(int j=0;j<=lon;j++){float phi=(float)j/lon*Mathf.PI*2;Vector3 n=new(Mathf.Sin(theta)*Mathf.Cos(phi),Mathf.Cos(theta),Mathf.Sin(theta)*Mathf.Sin(phi));float f=1+noise*(Mathf.PerlinNoise(n.x*2+seed,n.z*2+n.y*3+seed)-.5f)*2+noise*.035f*Mathf.Sin(n.x*11+n.y*9+n.z*13);Color c=Color.white*Mathf.Lerp(.68f,1,Mathf.Clamp01(n.y*.5f+.5f));c.a=Mathf.Lerp(.6f,1,n.y*.5f+.5f);Vertex(center+Vector3.Scale(n,scale)*f,new Vector2((float)j/lon,(float)i/lat),c);}}
  for(int i=0;i<lat;i++)for(int j=0;j<lon;j++){int a=start+i*(lon+1)+j;Quad(a,a+1,a+lon+2,a+lon+1);}
 }
 public static float RouteY(float z){if(z<0)return -4;for(int i=0;i<7;i++){if(z<OceanWorld.Centers[i+1].z){float t=Mathf.SmoothStep(0,1,(z-OceanWorld.Centers[i].z)/32);return Mathf.Lerp(OceanWorld.Centers[i].y,OceanWorld.Centers[i+1].y,t)-4;}}return -10;}
 public static float Floor(float x,float z){float channel=Mathf.Sin(z*.115f)*2;float edge=Mathf.SmoothStep(0,1,(Mathf.Abs(x-channel)-4)/9);float n=Mathf.PerlinNoise(x*.12f+10,z*.12f+20);float n2=Mathf.PerlinNoise(x*.38f+80,z*.38f+15);return RouteY(z)+edge*(1.5f+n*2)+n2*.18f+Mathf.Sin(z*6+x*.35f)*.025f;}
 public static Mesh Terrain(float z0,float z1){var b=new ReefGeometry();int nx=120,nz=70;for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++){float px=Mathf.Lerp(-45,45,(float)x/nx),pz=Mathf.Lerp(z0,z1,(float)z/nz);b.Vertex(new(px,Floor(px,pz),pz),new(px*.24f,pz*.24f),Color.white);}for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){int a=z*(nx+1)+x;b.Quad(a,a+nx+1,a+nx+2,a+1);}return b.Mesh("Continuous rippled seabed");}
 public static Mesh Rock(int seed){var b=new ReefGeometry();b.Ellipsoid(Vector3.zero,Vector3.one,40,56,.23f,seed);return b.Mesh("Eroded reef limestone "+seed);}
 public static Mesh Branching(int seed){Random.InitState(seed);var b=new ReefGeometry();for(int i=0;i<9;i++){float a=i*2.39996f;Vector3 p=new(Mathf.Cos(a)*Random.Range(.05f,.35f),0,Mathf.Sin(a)*Random.Range(.05f,.35f));b.Branch(p,new Vector3(Mathf.Cos(a)*.3f,1,Mathf.Sin(a)*.3f).normalized,Random.Range(.55f,.95f),.045f,3);}return b.Mesh("Acropora growth "+seed);}
 void Branch(Vector3 p,Vector3 dir,float len,float rad,int depth){Vector3 end=p+dir*len;Tube(new[]{p,Vector3.Lerp(p,end,.35f)+Vector3.up*.03f,Vector3.Lerp(p,end,.7f),end},new[]{rad,rad*.8f,rad*.55f,rad*.12f},7,Color.white);if(depth<=0)return;for(int i=0;i<3;i++){Vector3 d=(dir*.45f+Vector3.up*.4f+Random.onUnitSphere*.65f).normalized;if(d.y<.1f)d.y=.3f;Branch(Vector3.Lerp(p,end,Random.Range(.5f,.9f)),d,len*Random.Range(.48f,.7f),rad*.58f,depth-1);}}
 public static Mesh Plate(int seed){Random.InitState(seed);var b=new ReefGeometry();int rings=18,segments=96;for(int layer=0;layer<3;layer++){int start=b.v.Count;float radius=1-layer*.23f;for(int r=0;r<=rings;r++)for(int a=0;a<=segments;a++){float f=(float)r/rings,t=(float)a/segments*Mathf.PI*2;float rim=1+.08f*Mathf.Sin(t*7+seed)+.035f*Mathf.Sin(t*19);float y=layer*.23f+f*f*.18f+Mathf.Sin(t*12+f*8)*.035f*f+Mathf.Sin(f*90)*.006f;Color c=Color.Lerp(new Color(.55f,.52f,.49f),Color.white,f);c.a=1;b.Vertex(new(Mathf.Cos(t)*f*radius*rim,y,Mathf.Sin(t)*f*radius*rim),new Vector2(Mathf.Cos(t)*f,Mathf.Sin(t)*f)*.5f+Vector2.one*.5f,c);}for(int r=0;r<rings;r++)for(int a=0;a<segments;a++){int j=start+r*(segments+1)+a;b.Quad(j,j+1,j+segments+2,j+segments+1);}}return b.Mesh("Ruffled Montipora shelves "+seed);}
 public static Mesh Fan(int seed){Random.InitState(seed);var b=new ReefGeometry();for(int k=0;k<26;k++){float angle=Mathf.Lerp(-1.25f,1.25f,(float)k/25);var points=new Vector3[10];var radii=new float[10];for(int j=0;j<10;j++){float f=(float)j/9;points[j]=new(Mathf.Sin(angle)*f,Mathf.Cos(angle)*f+.15f,Mathf.Sin(f*5+angle*2)*.06f);radii[j]=Mathf.Lerp(.018f,.004f,f);}b.Tube(points,radii,5,Color.white);for(int j=2;j<9;j++){Vector3 end=points[j]+new Vector3(k<13?-.1f:.1f,.12f,Random.Range(-.025f,.025f));b.Tube(new[]{points[j],end},new[]{.007f,.002f},4,Color.white);}}
 for(int j=2;j<10;j++){var p=new Vector3[26];var r=new float[26];for(int k=0;k<26;k++){float a=Mathf.Lerp(-1.25f,1.25f,(float)k/25),f=j/9f;p[k]=new(Mathf.Sin(a)*f,Mathf.Cos(a)*f+.15f,Mathf.Sin(f*5+a*2)*.06f);r[k]=.0045f;}b.Tube(p,r,4,Color.white);}return b.Mesh("Gorgonian sea fan "+seed);}
 public static Mesh Sponge(int seed){Random.InitState(seed);var b=new ReefGeometry();for(int k=0;k<5;k++){float a=k*2.399f;Vector3 center=new(Mathf.Cos(a)*.25f,0,Mathf.Sin(a)*.25f);float height=Random.Range(.5f,1.2f),radius=Random.Range(.1f,.17f);int start=b.v.Count;int rings=24,sides=32;
 for(int r=0;r<=rings;r++)for(int s=0;s<=sides;s++){float f=(float)r/rings,t=(float)s/sides*Mathf.PI*2;float rr=radius*(.65f+.35f*Mathf.Sin(f*1.6f))*(1+.045f*Mathf.Sin(t*13+f*20));Vector3 p=center+new Vector3(Mathf.Cos(t)*rr+f*f*.1f,f*height,Mathf.Sin(t)*rr);b.Vertex(p,new((float)s/sides,f),Color.Lerp(new Color(.55f,.5f,.46f),Color.white,f));}
 for(int r=0;r<rings;r++)for(int s=0;s<sides;s++){int j=start+r*(sides+1)+s;b.Quad(j,j+sides+1,j+sides+2,j+1);}
 int inner=b.v.Count;for(int r=0;r<2;r++)for(int s=0;s<=sides;s++){float t=s*2*Mathf.PI/sides,rr=radius*(r==0?.95f:.65f);b.Vertex(center+new Vector3(Mathf.Cos(t)*rr+.1f,height-r*.24f,Mathf.Sin(t)*rr),new((float)s/sides,r),r==0?Color.white:new Color(.13f,.12f,.12f));}for(int s=0;s<sides;s++)b.Quad(inner+s,inner+s+1,inner+s+sides+2,inner+s+sides+1);
 }return b.Mesh("Porous tube sponge "+seed);}
 public static Mesh Grass(int seed){Random.InitState(seed);var b=new ReefGeometry();for(int k=0;k<32;k++){Vector3 baseP=new(Random.Range(-.3f,.3f),0,Random.Range(-.3f,.3f));float h=Random.Range(.3f,.85f),ang=Random.value*6.28f;Vector3 width=new(Mathf.Cos(ang),0,Mathf.Sin(ang));int start=b.v.Count;for(int j=0;j<=8;j++){float f=j/8f;Vector3 p=baseP+Vector3.up*(h*f)+new Vector3(Mathf.Sin(ang)*f*f*.3f,0,Mathf.Cos(ang)*f*f*.3f);float w=.025f*(1-f*.9f);Color c=Color.Lerp(new Color(.38f,.5f,.35f),Color.white,f);b.Vertex(p-width*w,new(0,f),c);b.Vertex(p+width*w,new(1,f),c);}for(int j=0;j<8;j++)b.Quad(start+j*2,start+j*2+1,start+j*2+3,start+j*2+2);}return b.Mesh("Seagrass meadow "+seed);}
 public static Mesh Fish(){var b=new ReefGeometry();int sides=18,rings=24;for(int r=0;r<=rings;r++){float t=(float)r/rings;float z=Mathf.Lerp(-.43f,.45f,t);float width=Mathf.Sin(Mathf.Pow(t,.75f)*Mathf.PI)*.12f+.006f;float height=Mathf.Sin(Mathf.Pow(t,.8f)*Mathf.PI)*.14f+.005f;for(int a=0;a<=sides;a++){float angle=a*2*Mathf.PI/sides;Color c=Color.Lerp(new Color(.5f,.53f,.55f),Color.white,Mathf.Sin(angle)*.5f+.5f);b.Vertex(new(Mathf.Cos(angle)*width,Mathf.Sin(angle)*height,z),new(t,(float)a/sides),c);}}for(int r=0;r<rings;r++)for(int a=0;a<sides;a++){int j=r*(sides+1)+a;b.Quad(j,j+1,j+sides+2,j+sides+1);}int p=b.Vertex(new(0,0,-.38f),new(0,0),Color.white),q=b.Vertex(new(0,.22f,-.68f),new(1,0),Color.white),s=b.Vertex(new(0,0,-.57f),new(1,.5f),Color.white),u=b.Vertex(new(0,-.22f,-.68f),new(1,1),Color.white);b.Tri(p,q,s);b.Tri(p,s,u);
 int da=b.Vertex(new(0,.08f,-.26f),Vector2.zero,Color.white),db=b.Vertex(new(0,.32f,-.15f),Vector2.up,Color.white),dc=b.Vertex(new(0,.13f,.2f),Vector2.one,Color.white);b.Tri(da,db,dc);return b.Mesh("Reef fish fusiform anatomy");}
 public static Mesh Ray(){var b=new ReefGeometry();int nx=48,nz=28;for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++){float u=(float)x/nx*2-1,f=(float)z/nz;float width=Mathf.Pow(Mathf.Sin(f*Mathf.PI),.6f)*2;float pz=Mathf.Lerp(-.9f,1,f);float py=(1-u*u)*.16f+Mathf.Pow(Mathf.Abs(u),2)*.12f*Mathf.Sin(f*6);b.Vertex(new(u*width,py,pz-Mathf.Abs(u)*.45f),new((float)x/nx,f),Color.white);}for(int z=0;z<nz;z++)for(int x=0;x<nx;x++){int j=z*(nx+1)+x;b.Quad(j,j+nx+1,j+nx+2,j+1);}b.Tube(new[]{new Vector3(0,.04f,-.8f),new(0,0,-1.5f),new(.1f,.03f,-2.6f)},new[]{.07f,.035f,.003f},8,Color.white);return b.Mesh("Manta diamond wings and tail");}
 public static Mesh TurtleFlipper(bool left){var b=new ReefGeometry();float sign=left?-1:1;int n=18;for(int i=0;i<=n;i++){float t=i/(float)n;float w=Mathf.Sin(t*Mathf.PI)*.22f+.012f;Vector3 p=new(sign*t*1.1f,Mathf.Sin(t*Mathf.PI)*.09f,-t*.3f);b.Vertex(p+Vector3.forward*w,new(0,t),Color.white);b.Vertex(p-Vector3.forward*w,new(1,t),Color.white);}for(int i=0;i<n;i++)b.Quad(i*2,i*2+1,i*2+3,i*2+2);return b.Mesh(left?"Left flipper":"Right flipper");}
}
}



